/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'; hits=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'govern(?:ed|ing)\\s+law|governed by|shall be governed|APPLICABLE LAW|construction, interpretation|10 Governing',l,re.I):
   hits.append((page,' '.join(lines[max(0,i-1):i+6])))
 print('\\nFILE',f.name[:-4])
 for p,t in hits: print('PAGE',p,t)
 if not hits:
  print('NO CLAUSE MATCH; LAST TEXT:',s[-6500:])
PY"

